import {playAnnouncement,stopForeground} from './audio.js?v=0.3.0';
let queue=[],running=false,skipCurrent=null;
export function announceAll(items){queue.push(...items);queueMicrotask(drain);}
export function clearAnnouncements(){queue=[];skipCurrent?.();stopForeground();}
async function drain(){if(running||!queue.length)return;running=true;const item=queue.shift(),root=document.createElement('dialog');root.className='announcement '+(item.major?'major':'');root.setAttribute('aria-label','人生喜报');const card=document.createElement('div');card.className='announcement-card';const badge=document.createElement('span');badge.className='eyebrow';badge.textContent=({grade:'学年喜报',school:'金榜新章',graduation:'学有所成',promotion:'任职喜报',marriage:'良缘天成',birth:'新生命的到来',retirement:'功成归田'})[item.type]||'人生新章';const h=document.createElement('h2');h.textContent=item.text;const skip=document.createElement('button');skip.textContent='跳过播报';skip.className='smallbtn';card.append(badge,h,skip);root.append(card);if(item.major){const bolt=document.createElement('div');bolt.className='lightning';bolt.setAttribute('aria-hidden','true');root.append(bolt);}document.body.append(root);root.showModal();const duration=Math.min(16000,Math.max(3000,item.text.length*180));let timer;const dismiss=new Promise(resolve=>{const finish=()=>{clearTimeout(timer);resolve();};timer=setTimeout(finish,duration);skipCurrent=()=>{stopForeground();finish();};skip.onclick=skipCurrent;root.addEventListener("cancel",e=>{e.preventDefault();skipCurrent?.();});});const played=playAnnouncement(item).catch(()=>({unavailable:true}));await Promise.race([played.then(()=>new Promise(r=>setTimeout(r,1100))),dismiss]);clearTimeout(timer);root.close();root.remove();skipCurrent=null;running=false;drain();}


